class NotenError(Exception):
    """Basis aller Fehler der Bibliothek."""

class UngueltigeNote(NotenError):
    def __init__(self, note):
        super().__init__(
            f"Note {note} nicht in 1-5")
        self.note = note

def notenschnitt(noten, *, runden=False):
    if not noten:
        raise ValueError("noten ist leer")
    for n in noten:
        if n not in range(1, 6):
            raise UngueltigeNote(n)
    s = sum(noten) / len(noten)
    return round(s, 1) if runden else s

try:
    notenschnitt([1, 7])
except NotenError as e:
    print(e, "|", e.note)
# Note 7 nicht in 1-5 | 7

